/** Tests FIRST. Original source + actual SessionManager/final context; supplied engine-menu intent,
 * TempDir storage and explicitly CONSTRUCTED historical profile controls. No native Title/FULL claim. Java UNRUN. */
@Isolated
class TestCdSelectedProfileModule {
 @TempDir Path temporary;
 private static CdGameDataSource cached;private static String cachedRoot;
 @BeforeEach void setup(){TestEnvironment.resetAll();SessionManager.clear();}
 @AfterEach void cleanup(){SessionManager.clear();TestEnvironment.resetAll();}
 @Test void strictCreationPreparesAFreshModuleWithoutPublishingLiveProgressOrAWorld()throws Exception{
  var s=source();var a=SonicCdGameModule.prepareSelectedProfile(s,new SaveManager(temporary),1,SonicCdGameModule.ProfileEntry.NEW_GAME);assertEquals("CREATED",a.outcome());assertEquals(Optional.of(true),a.persistentPublication());var m=a.module().orElseThrow();assertEquals(CdSelectedProfileVisit.Phase.PREPARED,m.selectedProfileState().phase());assertTrue(m.ipxProgressState().titleFlagsByte().isEmpty());assertNull(SessionManager.getCurrentWorldSession());assertThrows(IllegalStateException.class,()->m.createGame(s));assertEquals(CdSelectedProfileVisit.Phase.PREPARED,m.selectedProfileState().phase());
 }
 @Test void actualWorldNewGameCompletesLocalCacheSeparateReadAndRealWriteThenStopsBeforeR11()throws Exception{
  var s=source();var manager=new SaveManager(temporary);var m=prepare(s,manager,SonicCdGameModule.ProfileEntry.NEW_GAME);var programmeServices=m.programServicesState();open(m,s,context(1));assertEquals(CdSelectedProfileVisit.Programme.R11A,assertThrows(CdSelectedProfileVisit.Unowned.class,()->m.createGame(s)).programme());var v=m.selectedProfileState();assertEquals(CdSelectedProfileVisit.Phase.PROGRAMME_ENTRY,v.phase());assertEquals(OptionalInt.of(0),v.localSubPolicyByte());assertEquals(OptionalInt.of(0),m.ipxProgressState().savedLevel().word());assertEquals(OptionalInt.of(0x10),m.ipxProgressState().titleFlagsByte());assertEquals(OptionalInt.of(0),m.ipxProgressState().timeAttackUnlockByte());assertEquals(OptionalInt.of(0),m.ipxProgressState().timeStonesByte());assertEquals(OptionalInt.of(0),m.ipxProgressState().saveDisabledByte());assertSame(programmeServices,m.programServicesState());assertTrue(m.programServicesState().completedCalls().isEmpty());assertThrows(UnsupportedOperationException.class,m::requirePlayerFrame);assertEquals(List.of(OptionalInt.empty(),OptionalInt.empty()),v.temporary().orElseThrow().tail());assertEquals(List.of(CdSelectedProfileVisit.Call.INITIALIZATION_POLICY,CdSelectedProfileVisit.Call.LOCAL_SUB_POLICY_COPY,CdSelectedProfileVisit.Call.INITIALIZATION_WRSAVE,CdSelectedProfileVisit.Call.TEMPORARY_PREFIX_704,CdSelectedProfileVisit.Call.IPX_BOOT_READ,CdSelectedProfileVisit.Call.IPX_READ_FIELDS,CdSelectedProfileVisit.Call.INIT_SS2,CdSelectedProfileVisit.Call.GAME_LOOP_STORES,CdSelectedProfileVisit.Call.NEW_GAME_STORES,CdSelectedProfileVisit.Call.IPX_WRITE_READ,CdSelectedProfileVisit.Call.IPX_WRITE_FIELDS,CdSelectedProfileVisit.Call.IPX_WRITE_ACK,CdSelectedProfileVisit.Call.RUN_R11_ENTRY),v.calls());assertEquals(0,read(manager,s).mainFields().timeStonesByte());assertTrue(m.rewindAdapters().isEmpty());
 }
 @Test void retainedOriginNewGamePreservesOnlyActualNonresetFieldsAndOverlappingSaveLowByte()throws Exception{
  var s=source();var manager=new SaveManager(temporary);var old=historical(s,2,6,0x90,0x3F);manager.writeSlot("scd",1,old.encode());var a=SonicCdGameModule.prepareSelectedProfile(s,manager,1,SonicCdGameModule.ProfileEntry.NEW_GAME);assertEquals("EXISTING_VALID",a.outcome());var m=a.module().orElseThrow();open(m,s,context(1));assertThrows(CdSelectedProfileVisit.Unowned.class,()->m.createGame(s));var p=m.ipxProgressState();assertEquals(OptionalInt.of(0),p.savedLevel().word());assertEquals(OptionalInt.of(6),p.timeAttackUnlockByte());assertEquals(OptionalInt.of(0x90),p.titleFlagsByte());assertEquals(OptionalInt.of(0xF1),p.unknownBackupByte());assertEquals(OptionalInt.of(0),p.currentSpecialStageByte());assertEquals(OptionalInt.of(0),p.goodFuturesByte());assertEquals(OptionalInt.of(0),p.timeStonesByte());var stored=read(manager,s).mainFields();assertEquals(6,stored.levelPairWord());assertEquals(0x90,stored.titleFlagsByte());assertEquals(0,stored.goodFuturesByte());assertEquals(0x3F,m.selectedProfileState().temporary().orElseThrow().mainFields().timeStonesByte(),"SPX backup write does not refresh the independent temporary cache");
 }
 @Test void loadGameKeepsActualR31ProgressAndIndependentTemporaryTailBeforeItsTrueEntryFence()throws Exception{
  var s=source();var manager=new SaveManager(temporary);var old=historical(s,1,3,0x70,0x7F).withTail(List.of(OptionalInt.of(0xAA),OptionalInt.of(0xBB))).withPolicy(OptionalInt.of(0xF0));manager.writeSlot("scd",1,old.encode());var m=prepare(s,manager,SonicCdGameModule.ProfileEntry.LOAD_GAME);open(m,s,context(1));assertEquals(CdSelectedProfileVisit.Programme.R31A,assertThrows(CdSelectedProfileVisit.Unowned.class,()->m.createGame(s)).programme());var v=m.selectedProfileState();assertEquals(OptionalInt.of(0x103),m.ipxProgressState().savedLevel().word());assertEquals(OptionalInt.of(0x7F),m.ipxProgressState().timeStonesByte());assertEquals(0,v.subSpecial().orElseThrow().timeStonesSub());assertEquals(0,v.subSpecial().orElseThrow().stageId());assertEquals(0,v.subSpecial().orElseThrow().timer());assertEquals(0,v.subSpecial().orElseThrow().rings());assertEquals(OptionalInt.of(0x100),v.globals().orElseThrow().zoneAct());assertEquals(OptionalInt.of(3),v.globals().orElseThrow().lives());assertEquals(OptionalInt.of(0),v.globals().orElseThrow().amyCaptured());assertEquals(List.of(OptionalInt.empty(),OptionalInt.empty()),v.temporary().orElseThrow().tail());assertEquals(old.tail(),read(manager,s).tail());assertEquals(old.policy(),read(manager,s).policy());assertTrue(v.temporary().orElseThrow().policy().isEmpty());assertEquals(OptionalInt.of(0),m.ipxProgressState().saveDisabledByte());assertFalse(v.calls().contains(CdSelectedProfileVisit.Call.NEW_GAME_STORES));assertEquals(1,Collections.frequency(v.calls(),CdSelectedProfileVisit.Call.IPX_LOAD_READ));
 }
 @Test void rawOutOfRangeSavedZoneFollowsNativeFallthroughToNewGame()throws Exception{
  var s=source();var manager=new SaveManager(temporary);manager.writeSlot("scd",1,historical(s,255,9,0x70,0x31).encode());var m=prepare(s,manager,SonicCdGameModule.ProfileEntry.LOAD_GAME);open(m,s,context(1));assertEquals(CdSelectedProfileVisit.Programme.R11A,assertThrows(CdSelectedProfileVisit.Unowned.class,()->m.createGame(s)).programme());assertEquals(OptionalInt.of(0),m.ipxProgressState().savedLevel().word());assertEquals(OptionalInt.of(9),m.ipxProgressState().timeAttackUnlockByte());assertEquals(OptionalInt.of(3),m.selectedProfileState().globals().orElseThrow().lives());
 }
 @Test void missingAfterSelectionNeverRecreatesAtALiveReadAndPreservesTheRealPrefix()throws Exception{
  var s=source();var manager=new SaveManager(temporary);manager.writeSlot("scd",1,historical(s,1,3,0x70,7).encode());var m=prepare(s,manager,SonicCdGameModule.ProfileEntry.NEW_GAME);manager.deleteSlot("scd",1);open(m,s,context(1));var stopped=assertThrows(CdSelectedProfileVisit.StorageStop.class,()->m.createGame(s));assertEquals(SaveProfileAccess.Disposition.MISSING,stopped.disposition());assertFalse(Files.exists(temporary.resolve("scd/slot1.json")));assertEquals(List.of(CdSelectedProfileVisit.Call.INITIALIZATION_POLICY,CdSelectedProfileVisit.Call.LOCAL_SUB_POLICY_COPY),m.selectedProfileState().calls());assertTrue(m.ipxProgressState().titleFlagsByte().isEmpty());assertThrows(IllegalStateException.class,()->m.createGame(s));
 }
 @Test void exactOriginalErrorRetiresTheInvocationWithoutNormalizingOrReplayingIt()throws Exception{
  var s=source();var ordinary=new SaveManager(temporary);ordinary.writeSlot("scd",1,historical(s,1,3,0x70,7).encode());var original=new AssertionError("constructed reader fault");var manager=CdSelectedProfileTestStorage.errorOnRead(temporary,2,original);var m=prepare(s,manager,SonicCdGameModule.ProfileEntry.NEW_GAME);open(m,s,context(1));assertSame(original,assertThrows(AssertionError.class,()->m.createGame(s)));assertEquals(List.of(CdSelectedProfileVisit.Call.INITIALIZATION_POLICY,CdSelectedProfileVisit.Call.LOCAL_SUB_POLICY_COPY),m.selectedProfileState().calls());assertThrows(IllegalStateException.class,()->m.createGame(s));assertEquals(7,read(ordinary,s).mainFields().timeStonesByte());
 }
 @Test void actualFinalContextIsRequiredAndConstructedWorldCannotGrantInvocation()throws Exception{
  var s=source();var m=prepare(s,new SaveManager(temporary),SonicCdGameModule.ProfileEntry.NEW_GAME);var before=m.selectedProfileState();new WorldSession(m,m,s,context(1));assertThrows(IllegalStateException.class,()->m.createGame(s));assertSame(before,m.selectedProfileState());for(var c:List.of(context(2),SaveSessionContext.noSave("scd",new SelectedTeam("sonic",List.of()),0,0),SaveSessionContext.forSlot("soniccd",1,new SelectedTeam("sonic",List.of()),0,0))){open(m,s,c);assertThrows(IllegalStateException.class,()->m.createGame(s));assertSame(before,m.selectedProfileState());}var equalSource=new CdGameDataSource(s.release(),s.assets(),s.fmSoundAssets(),s.timeWarpPrograms(),s.act2Assets(),s.act2PastAssets(),s.act3FutureAssets(),s.r31aAssets(),s.initialSaveAssets());assertEquals(s.identity(),equalSource.identity());open(m,equalSource,context(1));assertThrows(IllegalStateException.class,()->m.createGame(equalSource));assertSame(before,m.selectedProfileState());open(m,s,context(1));assertThrows(CdSelectedProfileVisit.Unowned.class,()->m.createGame(s));
 }
 @Test void healthyWorldCaptureRestoresValuesWithoutDiskWriteAndForeignLifetimeRejects()throws Exception{
  var s=source();var reads=new java.util.concurrent.atomic.AtomicInteger();var manager=CdSelectedProfileTestStorage.counted(temporary,reads);var m=prepare(s,manager,SonicCdGameModule.ProfileEntry.NEW_GAME);var world=open(m,s,context(1)).getWorldSession();assertThrows(CdSelectedProfileVisit.Unowned.class,()->m.createGame(s));var registry=new RewindRegistry();WorldSessionPolicyAccess.registerRewind(world,registry);var snapshot=registry.capture();var before=m.selectedProfileState();int readCount=reads.get();byte[] disk=Files.readAllBytes(temporary.resolve("scd/slot1.json"));registry.restore(snapshot);assertSame(before,m.selectedProfileState());assertThrows(CdSelectedProfileVisit.Unowned.class,()->m.createGame(s));assertEquals(before.calls(),m.selectedProfileState().calls());assertEquals(readCount,reads.get());assertArrayEquals(disk,Files.readAllBytes(temporary.resolve("scd/slot1.json")));SessionManager.clear();assertThrows(IllegalStateException.class,registry::capture);var other=prepare(s,manager,SonicCdGameModule.ProfileEntry.NEW_GAME);var second=open(other,s,context(1)).getWorldSession();assertThrows(CdSelectedProfileVisit.Unowned.class,()->other.createGame(s));var foreign=new RewindRegistry();WorldSessionPolicyAccess.registerRewind(second,foreign);assertThrows(IllegalArgumentException.class,()->foreign.restore(snapshot));
 }
 @Test void genericProviderCannotRestoreCartridgeProgressOrReemitAnInitialSnapshot()throws Exception{
  var s=source();var m=prepare(s,new SaveManager(temporary),SonicCdGameModule.ProfileEntry.NEW_GAME);open(m,s,context(1));assertThrows(CdSelectedProfileVisit.Unowned.class,()->m.createGame(s));var p=m.getSaveSnapshotProvider();assertThrows(UnsupportedOperationException.class,()->p.capture(SaveReason.NEW_SLOT_START,RuntimeSaveContext.forNewGame(context(1))));assertThrows(UnsupportedOperationException.class,()->p.restoreProgress(null,3,0,Map.of()));
 }
 @Test void oldSourceAbsenceAndInvalidRequestsFailBeforeAnyStorageAccess()throws Exception{
  var s=source();var legacy=new CdGameDataSource(s.release(),s.assets(),s.fmSoundAssets(),s.timeWarpPrograms(),s.act2Assets(),s.act2PastAssets(),s.act3FutureAssets(),s.r31aAssets());var path=temporary.resolve("not-created");assertThrows(IllegalArgumentException.class,()->SonicCdGameModule.prepareSelectedProfile(legacy,new SaveManager(path),1,SonicCdGameModule.ProfileEntry.NEW_GAME));assertFalse(Files.exists(path));assertThrows(IllegalArgumentException.class,()->SonicCdGameModule.prepareSelectedProfile(s,new SaveManager(path),0,SonicCdGameModule.ProfileEntry.NEW_GAME));assertThrows(NullPointerException.class,()->SonicCdGameModule.prepareSelectedProfile(s,null,1,SonicCdGameModule.ProfileEntry.NEW_GAME));assertThrows(NullPointerException.class,()->SonicCdGameModule.prepareSelectedProfile(s,new SaveManager(path),1,null));assertFalse(Files.exists(path));assertThrows(UnsupportedOperationException.class,()->SonicCdGameModule.openingObjectsDevelopmentPlayer().getSaveSnapshotProvider());
 }
 @Test void corruptProfileDoesNotYieldAModuleOrFreshDefault()throws Exception{
  var s=source();Files.createDirectories(temporary.resolve("scd"));Files.writeString(temporary.resolve("scd/slot1.json"),"constructed invalid JSON");var a=SonicCdGameModule.prepareSelectedProfile(s,new SaveManager(temporary),1,SonicCdGameModule.ProfileEntry.NEW_GAME);assertEquals("CORRUPT",a.outcome());assertTrue(a.module().isEmpty());assertTrue(a.failure().isPresent());assertFalse(Files.exists(temporary.resolve("scd/slot1.json")));
 }
 @Test void synchronousWriteFaultRetainsPolicyPrefixWithoutAWriteOrCacheAcknowledgement()throws Exception{
  var s=source();var manager=new SaveManager(temporary);var m=prepare(s,manager,SonicCdGameModule.ProfileEntry.NEW_GAME);var file=temporary.resolve("scd/slot1.json");Files.delete(file);Files.createDirectory(file);open(m,s,context(1));var stopped=assertThrows(java.io.UncheckedIOException.class,()->m.createGame(s));assertNotNull(stopped.getCause());assertEquals(List.of(CdSelectedProfileVisit.Call.INITIALIZATION_POLICY,CdSelectedProfileVisit.Call.LOCAL_SUB_POLICY_COPY),m.selectedProfileState().calls());assertTrue(m.selectedProfileState().temporary().isEmpty());assertThrows(IllegalStateException.class,()->m.createGame(s));assertTrue(Files.isDirectory(file));
 }
 @Test void factoryAndOriginalPublicationCaptureConstructorsHaveTheBoundedSurface()throws Exception{
  var factory=SonicCdGameModule.class.getDeclaredMethod("prepareSelectedProfile",CdGameDataSource.class,SaveManager.class,int.class,SonicCdGameModule.ProfileEntry.class);assertTrue(java.lang.reflect.Modifier.isStatic(factory.getModifiers()));assertTrue(java.lang.reflect.Modifier.isPublic(factory.getModifiers()));assertEquals(SonicCdGameModule.SelectedProfileAttempt.class,factory.getReturnType());assertEquals(List.of("NEW_GAME","LOAD_GAME"),Arrays.stream(SonicCdGameModule.ProfileEntry.values()).map(Enum::name).toList());assertTrue(Arrays.stream(SonicCdGameModule.SelectedProfileAttempt.class.getDeclaredConstructors()).allMatch(c->java.lang.reflect.Modifier.isPrivate(c.getModifiers())));assertTrue(Arrays.stream(CdSelectedProfileVisit.Snapshot.class.getDeclaredConstructors()).allMatch(c->java.lang.reflect.Modifier.isPrivate(c.getModifiers())));assertTrue(Arrays.stream(CdSelectedProfileVisit.Publication.class.getDeclaredConstructors()).allMatch(c->java.lang.reflect.Modifier.isPrivate(c.getModifiers())));
 }
 @Test void laterZoneStopsBeforeItsUnownedProgressContinuationWithoutR31OrNewGameSubstitution()throws Exception{
  var s=source();var manager=new SaveManager(temporary);manager.writeSlot("scd",1,historical(s,2,6,0x70,0x31).encode());var m=prepare(s,manager,SonicCdGameModule.ProfileEntry.LOAD_GAME);open(m,s,context(1));assertEquals(CdSelectedProfileVisit.Programme.LATER_ZONE,assertThrows(CdSelectedProfileVisit.Unowned.class,()->m.createGame(s)).programme());var v=m.selectedProfileState();assertEquals(OptionalInt.of(0x206),v.globals().orElseThrow().zoneAct());assertFalse(v.calls().contains(CdSelectedProfileVisit.Call.NEW_GAME_STORES));assertFalse(v.calls().contains(CdSelectedProfileVisit.Call.IPX_WRITE_READ));assertFalse(v.calls().contains(CdSelectedProfileVisit.Call.RUN_R31_ENTRY));assertEquals(0x31,read(manager,s).mainFields().timeStonesByte());
 }
 @Test void sameWorldGameplayRecreationRetainsSelectionWithoutAnotherBootstrapOrSave()throws Exception{
  var s=source();var reads=new java.util.concurrent.atomic.AtomicInteger();var manager=CdSelectedProfileTestStorage.counted(temporary,reads);var m=prepare(s,manager,SonicCdGameModule.ProfileEntry.NEW_GAME);var first=open(m,s,context(1));assertThrows(CdSelectedProfileVisit.Unowned.class,()->m.createGame(s));var before=m.selectedProfileState();int count=reads.get();var second=SessionManager.reopenGameplaySession(com.openggf.game.timing.HardwareReadinessAdmissionPolicy.LIVE);assertSame(first.getWorldSession(),second.getWorldSession());assertSame(before,m.selectedProfileState());assertThrows(CdSelectedProfileVisit.Unowned.class,()->m.createGame(s));assertEquals(count,reads.get());assertSame(before,m.selectedProfileState());
 }
 @Test void reconstructedPolicyCannotCaptureRestoreOrRetireTheActualSelectedWorld()throws Exception{
  var s=source();var m=prepare(s,new SaveManager(temporary),SonicCdGameModule.ProfileEntry.NEW_GAME);var world=open(m,s,context(1)).getWorldSession();assertThrows(CdSelectedProfileVisit.Unowned.class,()->m.createGame(s));var provider=m.getGameService(WorldSessionPolicyProvider.class);var reconstructed=provider.open(world);assertThrows(IllegalStateException.class,()->reconstructed.rewindAdapter().capture());assertThrows(IllegalStateException.class,reconstructed::retire);var actual=WorldSessionPolicyAccess.getService(world,reconstructed.getClass());assertNotSame(reconstructed,actual);assertThrows(IllegalStateException.class,actual::retire);var before=m.selectedProfileState();assertThrows(CdSelectedProfileVisit.Unowned.class,()->m.createGame(s));assertSame(before,m.selectedProfileState());
 }
 @Test void anotherConstructedVisitAndValuePortCannotBorrowTheModulesActualInvocation()throws Exception{
  var s=source();var manager=new SaveManager(temporary);var m=prepare(s,manager,SonicCdGameModule.ProfileEntry.NEW_GAME);var world=open(m,s,context(1)).getWorldSession();var before=m.selectedProfileState();var data=CdSelectedProfileVisit.prepare(s,manager,1,SonicCdGameModule.ProfileEntry.NEW_GAME);var other=new CdSelectedProfileVisit(m,data,new Object());assertThrows(IllegalStateException.class,()->other.run(world,original->original.applyNative(m),new Object()));assertSame(before,m.selectedProfileState());assertThrows(CdSelectedProfileVisit.Unowned.class,()->m.createGame(s));
 }
 @Test void lateSynchronousWriteFailureKeepsAllOriginalFieldStoresAndNoCompletedWriteReceipt()throws Exception{
  var s=source();var base=new SaveManager(temporary);base.writeSlot("scd",1,historical(s,2,6,0x90,0x3F).encode());
  // Four is the documented strict-read operation ordinal: lookup, localRDSAVE, IPXboot, IPXwriteRead.
  var manager=CdSelectedProfileTestStorage.directoryAfterRead(temporary,4);var m=prepare(s,manager,SonicCdGameModule.ProfileEntry.NEW_GAME);open(m,s,context(1));assertThrows(java.io.UncheckedIOException.class,()->m.createGame(s));var v=m.selectedProfileState();assertEquals(CdSelectedProfileVisit.Phase.SAVE_FIELDS,v.phase());assertEquals(CdSelectedProfileVisit.Call.IPX_WRITE_FIELDS,v.calls().getLast());assertFalse(v.calls().contains(CdSelectedProfileVisit.Call.IPX_WRITE_ACK));assertFalse(v.calls().contains(CdSelectedProfileVisit.Call.RUN_R11_ENTRY));assertEquals(6,v.buffer().orElseThrow().mainFields().levelPairWord());assertEquals(0,v.buffer().orElseThrow().mainFields().timeStonesByte());assertEquals(0x3F,v.temporary().orElseThrow().mainFields().timeStonesByte());assertEquals(OptionalInt.of(0),m.ipxProgressState().timeStonesByte());assertEquals(OptionalInt.of(0x90),m.ipxProgressState().titleFlagsByte());assertTrue(Files.isDirectory(temporary.resolve("scd/slot1.json")));assertThrows(IllegalStateException.class,()->m.createGame(s));
 }
 private static SonicCdGameModule prepare(CdGameDataSource s,SaveManager manager,SonicCdGameModule.ProfileEntry e){return SonicCdGameModule.prepareSelectedProfile(s,manager,1,e).module().orElseThrow();}
 private static SaveSessionContext context(int slot){return SaveSessionContext.forSlot("scd",slot,new SelectedTeam("sonic",List.of()),0,0);}
 private static GameplayModeContext open(SonicCdGameModule m,CdGameDataSource s,SaveSessionContext c){return SessionManager.openGameplaySession(m,m,s,c);}
 private static CdSaveProfile read(SaveManager manager,CdGameDataSource s){var lookup=SaveProfileAccess.lookup(manager,"scd",1);assertEquals(SaveProfileAccess.Disposition.VALID,lookup.disposition());return CdSaveProfile.decode(s.initialSaveAssets().orElseThrow(),lookup.payload());}
 private static CdSaveProfile historical(CdGameDataSource s,int zone,int unlock,int title,int stones){return CdSaveProfile.fromTemplate(s.initialSaveAssets().orElseThrow()).withPatch(new CdIpxProgress.SavePatch(OptionalInt.of((zone<<8)|unlock),OptionalInt.of(0xA5),OptionalInt.of(title),OptionalInt.of(unlock),OptionalInt.of(0xF1),OptionalInt.of(5),OptionalInt.of(stones)));}
 private static synchronized CdGameDataSource source()throws Exception{String root=System.getProperty("soniccd.media.root");Assumptions.assumeTrue(root!=null&&!root.isBlank(),"Optional original USA source absent");if(cached!=null&&root.equals(cachedRoot))return cached;try(var files=Files.list(Path.of(root).resolve("USA"))){var cues=files.filter(v->v.getFileName().toString().toLowerCase(Locale.ROOT).endsWith(".cue")).toList();assertEquals(1,cues.size(),"Configured source requires exactly one original CUE");cached=CdStockLaunch.prepare(cues.getFirst(),CdStockLaunch.Request.r11a());cachedRoot=root;return cached;}}
}
